// Block (composition) — a section of expandable frequently asked questions.
// Accordion/AccordionItem own disclosure behavior and look; this Block supplies the question structure.
import type { ReactNode, Ref } from "react";
import { Accordion, AccordionItem } from "../components/Accordion";
import "./FaqAccordion.css";

export interface FaqAccordionProps {
  items: {
    id: string;
    question: string;
    answer: ReactNode;
  }[];
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function FaqAccordion({ items, className, ref }: FaqAccordionProps) {
  return (
    <section
      ref={ref}
      aria-label="Frequently asked questions"
      className={className ? `sd-faqaccordion ${className}` : "sd-faqaccordion"}
    >
      <Accordion>
        {items.map((item) => (
          <AccordionItem key={item.id} id={item.id} title={item.question} headingLevel={2}>
            {item.answer}
          </AccordionItem>
        ))}
      </Accordion>
    </section>
  );
}

/* A Panel: its width is the page's (block-contract.md §1b), so its left edge stays on the page grid
   with every section around it. */
.sd-faqaccordion {
  width: 100%;
}
